wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(73396952616468535813)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Escalate Report Process'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_report_id NUMBER := TO_NUMBER(apex_application.g_x01);',
'    l_location police_refusal_reports.location%TYPE;',
'    l_description police_refusal_reports.refusal_description%TYPE;',
'    l_date_submitted police_refusal_reports.date_submitted%TYPE;',
'BEGIN',
'    --  Update escalation status & fetch details',
'    UPDATE police_refusal_reports',
'       SET escalated_flag = ''Y'',',
'           escalated_on   = SYSDATE',
'     WHERE report_id = l_report_id',
'     RETURNING location, refusal_description, date_submitted',
'     INTO l_location, l_description, l_date_submitted;',
'',
'    COMMIT;',
'',
'    --  Send WhatsApp msg via webhook',
'    send_escalation_to_make(l_report_id);',
'',
'    --  Send escalation email',
'    APEX_MAIL.SEND(',
'        p_to    => ''datadragons25@gmail.com'',--mail',
'        p_from  => ''x25_data_dragons@apex.oracle.com'',      ',
unistr('        p_subj  => ''\D83D\DEA8 Escalation: Police Refusal Case #'' || l_report_id,'),
'        p_body  => ''Dear Officer,'' || CHR(10) || CHR(10) ||',
'                   ''A police refusal report has been escalated.'' || CHR(10) ||',
'                   ''Details:'' || CHR(10) ||',
'                   ''Location: '' || l_location || CHR(10) ||',
'                   ''Description: '' || l_description || CHR(10) ||',
'                   ''Date Submitted: '' || TO_CHAR(l_date_submitted, ''DD-Mon-YYYY HH24:MI'') || CHR(10) || CHR(10) ||',
'                   ''Please take immediate action.''',
'    );',
'    APEX_MAIL.PUSH_QUEUE;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>73396952616468535813
);
end;
